create function private.school_access_state() returns jsonb language sql stable security definer set search_path='' as $$ select case when private.has_school_role(array['headmaster','dean','discipline_officer','discipline_staff','teacher','student']) then (select jsonb_build_object('roles',(select jsonb_agg(r.role order by r.role)from public.user_roles r where r.user_id=p.id),'display_name',p.display_name)from public.profiles p where p.id=auth.uid())else null end; $$; create function public.school_access_state() returns jsonb language sql stable security invoker set search_path=''as $$select private.school_access_state();$$;revoke all on function private.school_access_state(),public.school_access_state()from public,anon;grant execute on function private.school_access_state(),public.school_access_state()to authenticated;
